// Frase do dia + devocional. Um item por dia, em rodízio.
// r: [livro, cap., vers.]  t: título  ctx: contexto histórico  w: [hebraico, transliteração, significado]
// p: reflexão (parágrafos)  ecos: [livro, cap., vers., comentário]  pr: prática  q: perguntas  or: oração
const DAILY = [
{ r: [6, 1, 9], t: 'Coragem que vem da presença',
  ctx: 'Moisés acabou de morrer. Josué, seu auxiliar por quarenta anos, herda um povo inteiro e a tarefa de atravessar o Jordão na época da cheia (Js 3:15) para entrar numa terra de cidades muradas. Deus repete a ordem "sê forte e corajoso" três vezes no capítulo (v. 6, 7 e 9), e o próprio povo a repete uma quarta vez (v. 18).',
  w: ['חֲזַק', 'chazaq', '"Sê forte, firma-te." O verbo também significa agarrar, segurar com força, e é usado para pegar alguém pela mão. Da mesma raiz vem o nome Ezequias (Chizqiyahu, "o Senhor fortalece").'],
  p: ['A ordem nunca vem sozinha. Em todas as vezes ela traz um motivo: "porque o Senhor teu Deus é contigo por onde quer que andares". A coragem bíblica não é um traço de personalidade de quem nasceu destemido. É consequência de saber quem está ao lado. Josué não precisava se sentir forte; precisava se lembrar de uma presença.',
    'Repare no versículo 8, logo antes: a firmeza de Josué estaria ligada a meditar na Torá "de dia e de noite". Coragem e Palavra andam juntas. O medo cresce quando a voz das circunstâncias é a única que ouvimos, e a coragem cresce quando outra voz fala mais alto. Josué entraria em Canaã com um livro, não só com uma espada.',
    '"Não te assustes" (al ta’arots) descreve o tremor diante de algo que parece maior do que nós. Deus não diz que os inimigos são pequenos: as cidades eram de fato fortificadas. Ele diz que a presença dele é maior. A fé não nega o tamanho do problema; ela o coloca ao lado do tamanho de Deus.'],
  ecos: [[5, 31, 6, 'Moisés já tinha dado a mesma palavra ao povo'], [19, 27, 1, 'A quem temerei?'], [40, 28, 20, 'Jesus repete a promessa a quem é enviado']],
  pr: 'Escreva num papel a tarefa que mais te intimida hoje e, ao lado dela, "o Senhor teu Deus é contigo". Antes de começar, leia em voz alta.',
  q: ['Que voz tem falado mais alto em você: a das circunstâncias ou a da Palavra?', 'Em que área você está esperando sentir coragem antes de obedecer?'],
  or: 'Senhor, tu não me pedes para fingir uma força que não tenho. Ajuda-me a me agarrar a ti. Vai comigo aos lugares que me assustam hoje. Amém.' },

{ r: [19, 23, 1], t: 'O Pastor que conhece cada ovelha',
  ctx: 'Salmo atribuído a Davi, que passou a juventude cuidando das ovelhas do pai em Belém e chegou a defendê-las de leões e ursos (1Sm 16:11; 17:34-35). No antigo Oriente, "pastor" era também título de reis: governar era pastorear. Davi, já rei, se coloca no lugar da ovelha.',
  w: ['רֹעִי', 'ro’i', '"Meu pastor", da raiz ra’ah: apascentar, alimentar, cuidar. Uma raiz muito parecida forma re’a, "amigo, companheiro". O pastor é alguém que convive com o rebanho dia e noite.'],
  p: ['Em hebraico o salmo começa com quatro palavras: Adonai ro’i lo echsar, "o Senhor é meu pastor, nada me faltará". A segunda afirmação depende da primeira. Não nos falta nada não porque temos tudo, mas porque pertencemos a alguém que cuida.',
    'Note o movimento do salmo. Nos versículos 1 a 3, Davi fala sobre Deus: "ele me faz repousar". No versículo 4, ao entrar no vale da sombra da morte, passa a falar com Deus: "tu estás comigo". É no escuro que falar sobre Deus vira falar com Deus. As crises tiram a fé da terceira pessoa e a levam para a segunda.',
    'O salmo termina dizendo que "bondade e misericórdia me seguirão". O verbo radaph significa "perseguir" e é usado para inimigos numa caçada. Davi, que foi perseguido por Saul e depois pelo próprio filho Absalão, inverte a imagem: o que corre atrás dele para alcançá-lo é o chesed, o amor leal de Deus.'],
  ecos: [[26, 34, 11, 'O próprio Deus buscará as suas ovelhas'], [43, 10, 11, 'O bom pastor dá a vida pelas ovelhas'], [60, 2, 25, 'Voltastes ao Pastor das vossas almas']],
  pr: 'Releia o Salmo 23 devagar trocando cada "ele" por "tu", transformando o salmo em oração.',
  q: ['Em que área você vive como se lhe faltasse algo, mesmo tendo um Pastor?', 'Que vale você está atravessando agora? Já começou a falar com Deus ali, ou só sobre ele?'],
  or: 'Senhor, meu pastor, conduze-me hoje às águas tranquilas. Se o caminho passar pelo vale, que eu saiba que estás comigo. Que a tua bondade me alcance. Amém.' },

{ r: [23, 40, 31], t: 'Esperar que renova',
  ctx: 'Isaías 40 abre a segunda grande parte do livro, dirigida ao povo exilado na Babilônia no século VI a.C. Depois de décadas longe de casa, muitos diziam: "o meu caminho está encoberto ao Senhor" (v. 27). O capítulo responde mostrando a grandeza do Criador, que "não se cansa nem se fatiga" (v. 28).',
  w: ['קוֹוֵי', 'qovê', '"Os que esperam", da raiz qavah. Dela vem qav, "corda, fio de medir", e tiqvah, "esperança". Esperar é ficar ligado, como uma corda esticada, àquilo que há de vir.'],
  p: ['O versículo 30 prepara o contraste: "os jovens se cansam e se fatigam, e os moços caem". Até quem tem força natural chega ao limite. A promessa não é para os fortes, é para os que esperam. A diferença não está na energia de quem corre, mas na fonte de onde ela vem.',
    '"Renovarão as forças" traduz yachalifu koach, literalmente "trocarão a força". A imagem é de quem troca uma roupa gasta por uma nova. Esperar no Senhor não é acumular mais da mesma força; é receber outra, que não é nossa.',
    'Repare na ordem: voar, correr, andar. Parece invertida, pois seria natural terminar no mais impressionante. Mas a vida, na maior parte do tempo, é andar. Há dias de águia, porém a promessa mais preciosa talvez seja a última: caminhar sem desfalecer, um passo depois do outro, nos dias comuns.'],
  ecos: [[19, 27, 14, 'Espera no Senhor, anima-te'], [25, 3, 25, 'Bom é o Senhor para os que esperam por ele'], [47, 4, 16, 'O homem interior se renova dia após dia']],
  pr: 'Separe cinco minutos hoje para parar e entregar a Deus o que te cansa. Diga em voz alta, com nome, o que está te esgotando.',
  q: ['Você está tentando correr com a força antiga?', 'O que significa, nesta fase da sua vida, "andar e não desfalecer"?'],
  or: 'Deus eterno, que não te cansas nem te fatigas, troca a minha força gasta pela tua. Ensina-me a esperar ligado a ti. Amém.' },

{ r: [5, 6, 5], t: 'Amar com tudo',
  ctx: 'Deuteronômio reúne os discursos de Moisés nas planícies de Moabe, às vésperas da entrada em Canaã. Os versículos 6:4-9 formam o Shemá, recitado pelos judeus de manhã e à noite até hoje. Jesus chamou este versículo de "o primeiro e grande mandamento" (Mt 22:37-38).',
  w: ['לְבָבְךָ', 'levavkha', '"Teu coração." Na Bíblia hebraica o coração (lev/levav) é a sede do pensamento, da memória e das decisões; "dizer no coração" é pensar. Os rabinos notaram as duas letras bet em levav e ensinaram: ame a Deus com os dois impulsos, o bom e o mau.'],
  p: ['Coração, alma (nefesh) e força (me’od). Nefesh é a vida inteira, o fôlego. Me’od é literalmente "muito", e a tradição judaica o entendeu como "com todos os teus recursos". As três palavras não descrevem partes separadas da pessoa, mas círculos cada vez maiores: o interior, a vida e tudo o que se possui.',
    'É curioso que o amor seja ordenado. No mundo antigo, os tratados entre reis e vassalos usavam "amar" no sentido de lealdade: amar o rei era ser fiel a ele. O amor pedido aqui não é antes de tudo uma emoção, mas uma lealdade escolhida todos os dias. As emoções acompanham com o tempo.',
    'Os versículos seguintes mostram onde esse amor mora: nas conversas com os filhos, "assentado em tua casa, andando pelo caminho, ao deitar-te e ao levantar-te" (v. 7), e até nos umbrais da casa. O amor a Deus não fica reservado ao templo. Ele se aprende no cotidiano, entre a porta de casa e a mesa.'],
  ecos: [[40, 22, 37, 'O primeiro e grande mandamento'], [5, 10, 12, 'Que pede o Senhor de ti?'], [62, 4, 19, 'Nós o amamos porque ele nos amou primeiro']],
  pr: 'Escolha uma área (pensamentos, tempo ou dinheiro) e faça hoje um gesto concreto de lealdade a Deus nela.',
  q: ['Seu amor a Deus tem sido mais emoção ou mais lealdade?', 'Que parte da sua rotina (casa, caminho, deitar, levantar) ainda não respira esse amor?'],
  or: 'Senhor, tu me amaste primeiro. Recebe meu coração, minha vida e tudo o que tenho. Que eu te ame não só com palavras, mas no meu dia comum. Amém.' },

{ r: [33, 6, 8], t: 'O que Deus realmente pede',
  ctx: 'Miqueias profetizou em Judá no século VIII a.C., na mesma época de Isaías, num tempo de prosperidade para poucos: terras tomadas à força, balanças falsas, juízes subornados (Mq 2:2; 3:11; 6:11). O capítulo 6 é montado como um tribunal em que Deus apresenta sua queixa contra o povo (v. 1-2).',
  w: ['חֶסֶד', 'chesed', 'Amor leal, bondade que permanece. É a palavra de aliança por excelência e aparece cerca de 250 vezes no Tanakh. Não tem equivalente exato em português: mistura amor, fidelidade e misericórdia.'],
  p: ['Nos versículos 6 e 7, a pergunta do povo vai ficando cada vez mais exagerada: holocaustos? bezerros de um ano? milhares de carneiros? rios de azeite? o filho primogênito? A lógica é de comércio: quanto preciso pagar para Deus ficar satisfeito? A resposta desmonta a pergunta. Deus não quer um preço; quer pessoas.',
    'São três coisas. "Praticar a justiça" (asot mishpat): fazer, não só opinar. "Amar a misericórdia" (ahavat chesed): não apenas fazer o bem, mas gostar de fazê-lo. "Andar humildemente" (hatsnea lekhet): literalmente andar com cuidado, discretamente, ao lado de Deus. Justiça com os outros, bondade no coração, humildade diante de Deus.',
    'O versículo começa com "Ele te declarou, ó homem, o que é bom". Não era uma revelação nova; já estava dito. O problema de Israel não era falta de informação, era falta de prática. Muitas vezes nós também pedimos a Deus que mostre a sua vontade em assuntos que ele já deixou claros.'],
  ecos: [[28, 6, 6, 'Misericórdia quero, e não sacrifício'], [30, 5, 24, 'Corra o juízo como as águas'], [40, 23, 23, 'Jesus: a justiça, a misericórdia e a fé']],
  pr: 'Encontre uma situação em que você pode agir com justiça hoje (um pagamento, uma palavra honesta, alguém que precisa ser defendido) e aja.',
  q: ['Em que você tem tentado "pagar" a Deus em vez de se entregar?', 'Você ama a bondade ou só a pratica quando é cobrado?'],
  or: 'Senhor, tu já me mostraste o que é bom. Dá-me mãos justas, um coração que ame a bondade e passos humildes ao teu lado. Amém.' },

{ r: [20, 3, 5], t: 'Confiar sem se apoiar no próprio entendimento',
  ctx: 'Os capítulos 1 a 9 de Provérbios são discursos de um pai ao filho, preparando-o para a vida adulta. O capítulo 3 une confiança em Deus, generosidade e aceitação da correção. Boa parte do livro é atribuída a Salomão, conhecido por sua sabedoria (1Rs 4:29-34).',
  w: ['בְּטַח', 'betach', '"Confia", de batach: estar seguro, apoiar-se. A imagem de fundo é a de deitar o peso sobre algo firme. Batach é o contrário de viver em estado de alerta.'],
  p: ['"Não te estribes no teu próprio entendimento" usa o verbo sha’an: apoiar-se como quem se encosta num cajado ou numa parede. O entendimento não é desprezado; Provérbios inteiro é um elogio à inteligência. O problema é fazer dele o apoio final. Uma bengala é útil, mas ninguém deve pôr todo o peso do corpo numa bengala de vidro.',
    '"Reconhece-o em todos os teus caminhos" traduz da’ehu, "conhece-o". Não é só lembrar de Deus no começo de um projeto, mas conhecê-lo dentro de cada caminho: no trabalho, nas finanças, nas relações. A confiança em Deus é fruto de conhecê-lo de perto.',
    '"Ele endireitará as tuas veredas" (yeyasher) pode significar tanto "tornar reto" quanto "aplanar, tirar os obstáculos". Não é promessa de caminho sem curvas, mas de caminho que chega ao lugar certo. O versículo 7 completa: "não sejas sábio aos teus próprios olhos". A confiança começa quando admitimos que não enxergamos tudo.'],
  ecos: [[19, 37, 5, 'Entrega o teu caminho ao Senhor'], [24, 17, 7, 'Bendito o homem que confia no Senhor'], [59, 1, 5, 'Se alguém tem falta de sabedoria, peça-a a Deus']],
  pr: 'Antes de uma decisão de hoje, pare e ore em uma frase: "Senhor, o que tu sabes que eu não sei?" Depois decida.',
  q: ['Em que área você tem posto todo o peso no seu próprio entendimento?', 'Você conhece a Deus dentro do seu trabalho ou só nos momentos de culto?'],
  or: 'Pai, eu enxergo pouco e tu vês o caminho inteiro. Ensina-me a me apoiar em ti e a te conhecer em cada passo de hoje. Amém.' },

{ r: [19, 121, 2], t: 'De onde vem o socorro',
  ctx: 'O Salmo 121 faz parte dos "Cânticos das Subidas" (Sl 120 a 134), cantados pelos peregrinos que subiam a Jerusalém para as festas. O caminho passava por montes cheios de perigos: assaltantes, sol forte de dia, frio à noite.',
  w: ['עֶזְרִי', 'ezri', '"Meu socorro", de ezer. É a mesma palavra usada para a mulher em Gn 2:18 ("auxiliadora") e, na maioria das vezes, para o próprio Deus. Ezer não é ajuda de alguém inferior; é o socorro de quem tem o que nos falta.'],
  p: ['"Elevo os olhos para os montes: de onde me virá o socorro?" Os montes podiam ser ameaça (esconderijo de ladrões) ou falsa segurança (os "altos" onde se adoravam ídolos). O peregrino olha para eles e faz a pergunta certa. A resposta passa por cima dos montes: o socorro vem daquele que os fez.',
    'O salmo usa seis vezes o verbo shamar, "guardar". Deus guarda o teu pé de tropeçar, não cochila nem dorme, guarda a tua saída e a tua entrada. "Não dormita nem dorme o guarda de Israel" contrasta com os deuses de Canaã: Elias zombou de Baal dizendo que talvez ele estivesse dormindo (1Rs 18:27).',
    '"A tua saída e a tua entrada, desde agora e para sempre" é uma expressão hebraica para a vida inteira: sair para o trabalho e voltar para casa, começar e terminar. Não há trecho da jornada fora do cuidado de Deus, nem o banal nem o perigoso.'],
  ecos: [[19, 46, 1, 'Socorro bem presente na angústia'], [23, 41, 10, 'Eu te ajudo, eu te sustento'], [58, 13, 6, 'O Senhor é o meu ajudador, não temerei']],
  pr: 'Ao sair de casa hoje e ao voltar, diga: "O Senhor guarda a minha saída e a minha entrada."',
  q: ['Para quais "montes" você tem olhado em busca de socorro?', 'Que parte da sua rotina você acha pequena demais para Deus guardar?'],
  or: 'Criador dos céus e da terra, o meu socorro vem de ti. Guarda os meus passos hoje, a minha saída e a minha entrada. Amém.' },

{ r: [1, 1, 27], t: 'Feitos à imagem de Deus',
  ctx: 'Gênesis 1 foi escrito num mundo em que outros povos contavam a criação como uma guerra entre deuses, e o ser humano como escravo feito para aliviar o trabalho deles (como nos poemas babilônicos Enuma Elish e Atrahasis). Gênesis apresenta outra visão: um único Deus cria pela palavra, e o ser humano é a coroa da criação.',
  w: ['צֶלֶם', 'tselem', '"Imagem." No antigo Oriente, os reis colocavam sua estátua (tselem) nas terras conquistadas para marcar seu domínio. Deus coloca sua imagem viva em toda a terra: cada ser humano.'],
  p: ['No Egito e na Mesopotâmia, só o rei era chamado "imagem do deus". Gênesis estende o título a todos: todo homem e toda mulher carregam a imagem de Deus. Não há pessoa sem dignidade, nem o escravo, nem o estrangeiro, nem o doente. Essa frase foi uma revolução silenciosa.',
    'O versículo tem ritmo de poema: "criou Deus o homem à sua imagem; à imagem de Deus o criou; homem e mulher os criou". O verbo bara aparece três vezes, e na Bíblia ele é usado apenas para a ação de Deus. Homem e mulher juntos refletem a imagem; nenhum dos dois sozinho a esgota.',
    'Ser imagem é também vocação. O versículo 28 dá a tarefa: governar e cuidar da criação como representantes de Deus. A imagem não é só algo que temos, mas algo que fazemos: refletir o caráter de Deus no modo como tratamos as pessoas e o mundo.'],
  ecos: [[19, 8, 5, 'Pouco menor que os anjos, coroado de glória'], [59, 3, 9, 'Não amaldiçoar quem foi feito à semelhança de Deus'], [51, 3, 10, 'Renovados segundo a imagem do Criador']],
  pr: 'Escolha alguém difícil de amar e, ao encontrá-lo hoje, lembre conscientemente: esta pessoa carrega a imagem de Deus.',
  q: ['Você se trata como portador da imagem de Deus?', 'Quem você tem tratado como se não a carregasse?'],
  or: 'Criador, obrigado por me fazer à tua imagem. Ajuda-me a ver o teu reflexo em cada pessoa e a refletir o teu caráter no que eu faço. Amém.' },

{ r: [23, 41, 10], t: 'Não temas',
  ctx: 'Isaías 41 fala a Israel no exílio, enquanto Ciro, rei da Pérsia, avançava conquistando nações (v. 2-5). Os povos das ilhas tremiam e fabricavam ídolos para se proteger (v. 6-7). Em contraste, Deus chama Israel de "meu servo, a quem escolhi, descendência de Abraão, meu amigo" (v. 8).',
  w: ['תְּמַכְתִּיךָ', 'tamakhtikha', '"Eu te sustento", de tamakh: segurar com firmeza, apoiar para que não caia. O verso acrescenta "com a destra da minha justiça": a mão direita era a mão da força.'],
  p: ['As nações vizinhas, com medo, fabricam ídolos e os fixam com pregos "para que não se movam" (v. 7). É uma ironia: o deus delas precisa ser segurado. Com Israel acontece o contrário. Não é o povo que segura o seu Deus; é Deus quem segura o seu povo.',
    'O versículo traz cinco afirmações em sequência: eu sou contigo, eu sou o teu Deus, eu te fortaleço, eu te ajudo, eu te sustento. Em todas, Deus é o sujeito. A ordem "não temas" não é um pedido de autocontrole; é um convite a olhar para essas cinco promessas.',
    '"Não te assombres" traduz al tishta, de sha’ah: olhar em volta com ansiedade, como quem procura uma saída. O medo nos faz olhar para todos os lados ao mesmo tempo. A resposta de Deus é: olhe para mim, "porque eu sou o teu Deus".'],
  ecos: [[23, 43, 2, 'Quando passares pelas águas, estarei contigo'], [19, 23, 4, 'Não temerei mal algum'], [45, 8, 31, 'Se Deus é por nós, quem será contra nós?']],
  pr: 'Leia o versículo em voz alta trocando "te" pelo seu nome.',
  q: ['O que você tem tentado "pregar no lugar" por medo de que se mova?', 'Qual das cinco promessas você mais precisa ouvir hoje?'],
  or: 'Senhor, quando eu olhar em volta com medo, faze-me olhar para ti. Segura-me com a tua mão direita. Amém.' },

{ r: [19, 119, 105], t: 'Lâmpada para os passos',
  ctx: 'O Salmo 119 é o capítulo mais longo da Bíblia, com 176 versos. É um acróstico: 22 estrofes de oito versos, uma para cada letra do alfabeto hebraico, e todos os versos de uma estrofe começam com a mesma letra. O versículo 105 abre a estrofe da letra nun (נ) e começa com ner, "lâmpada".',
  w: ['נֵר', 'ner', 'Pequena lamparina de barro com azeite e pavio. Ilumina apenas um pouco ao redor de quem a carrega: alguns passos de cada vez.'],
  p: ['O salmista não diz que a Palavra é um sol que ilumina a estrada inteira, mas uma lâmpada para os pés. Numa noite antiga, sem luz nas ruas, a lamparina mostrava só o próximo passo. A Palavra de Deus raramente nos mostra o caminho todo de uma vez; mostra o suficiente para o próximo passo fiel.',
    'O salmo inteiro gira em torno da Palavra usando oito sinônimos: torah, edut, piqqudim, mitsvah, mishpat, chuqqim, davar e imrah. Quase todo verso menciona pelo menos um deles. Não é leitura por obrigação; é paixão: "Quanto amo a tua lei! É a minha meditação o dia todo" (v. 97).',
    'Os versos seguintes mostram que o salmista não vivia num lugar tranquilo: "a minha vida está sempre em perigo" e "os ímpios me armaram laço" (v. 109-110). A lâmpada é necessária justamente porque é noite. A Palavra não elimina a escuridão, mas impede que ela decida os nossos passos.'],
  ecos: [[20, 6, 23, 'O mandamento é lâmpada, e a instrução é luz'], [43, 8, 12, 'Eu sou a luz do mundo'], [61, 1, 19, 'Uma candeia que brilha em lugar escuro']],
  pr: 'Escolha um versículo da sua leitura de hoje e leve-o com você: anote no celular ou num papel e releia três vezes ao longo do dia.',
  q: ['Você está pedindo a Deus a estrada inteira quando ele te oferece o próximo passo?', 'Qual é o próximo passo que a Palavra já iluminou para você?'],
  or: 'Senhor, a tua palavra é a minha lâmpada. Não te peço o mapa inteiro, só luz para o próximo passo. Amém.' },

{ r: [25, 3, 23], t: 'Novas a cada manhã',
  ctx: 'Lamentações chora a destruição de Jerusalém pelos babilônios em 586 a.C.: o templo queimado, fome, morte nas ruas. Os quatro primeiros capítulos são acrósticos. Bem no centro do livro, no meio do capítulo 3, aparece a esperança.',
  w: ['חֲדָשִׁים', 'chadashim', '"Novas", de chadash, "novo". Da mesma raiz vem chodesh, "mês": a lua nova que volta a aparecer no céu.'],
  p: ['Importa onde este versículo está. Não foi escrito num dia bom. O autor acabou de dizer que Deus o "fez andar em trevas", o "cercou de um muro" e "quebrou com pedrinhas os seus dentes" (v. 2-16). A esperança dos versículos 21 a 23 nasce no meio dos escombros, não depois que tudo se resolveu.',
    'O versículo 21 mostra o ponto de virada: "Quero trazer à memória o que me pode dar esperança". A situação não mudou; mudou aquilo para onde o autor decidiu olhar. A esperança bíblica é, muitas vezes, um ato deliberado de memória.',
    'As misericórdias do Senhor (rachamim) "renovam-se cada manhã". Rachamim vem de rechem, "ventre materno": é um amor de entranhas, de mãe. Como o maná no deserto (Êx 16), essa misericórdia não pode ser estocada. Ela chega a cada manhã, suficiente para cada dia.'],
  ecos: [[2, 16, 4, 'O maná recolhido a cada dia'], [19, 30, 5, 'Ao amanhecer vem a alegria'], [40, 6, 34, 'Basta a cada dia o seu mal']],
  pr: 'Amanhã, ao acordar, antes de pegar o celular, diga: "Grande é a tua fidelidade." Hoje à noite, anote uma misericórdia que você recebeu.',
  q: ['O que você precisa trazer à memória para ter esperança hoje?', 'Você está tentando viver da graça de ontem, em vez de recebê-la nova hoje?'],
  or: 'Senhor, mesmo nos escombros a tua misericórdia não acaba. Obrigado pela graça desta manhã. Grande é a tua fidelidade. Amém.' },

{ r: [24, 29, 11], t: 'Planos de paz',
  ctx: 'Jeremias escreve uma carta aos judeus já levados para a Babilônia (por volta de 597 a.C.). Falsos profetas prometiam uma volta rápida (Jr 28). Jeremias diz o contrário: o exílio duraria setenta anos (v. 10). Por isso: construam casas, plantem pomares, casem-se e "procurem a paz da cidade" (v. 5-7).',
  w: ['שָׁלוֹם', 'shalom', 'Muito mais que ausência de guerra: inteireza, integridade, tudo no lugar certo. O verbo da mesma raiz, shalem, significa "completar" e também "pagar uma dívida por inteiro".'],
  p: ['Este versículo costuma ser lido como promessa de sucesso imediato. No contexto, é quase o oposto: foi dito a quem passaria a vida inteira no exílio. Muitos dos que ouviram a carta morreriam na Babilônia. O plano de paz incluía esperar e ser fiel num lugar que ninguém tinha escolhido.',
    '"Pensamentos de paz, e não de mal": a palavra para mal (ra’ah) também significa "desgraça". Deus afirma que o exílio não era o fim, e sim parte de um propósito maior. "Para vos dar um futuro e uma esperança" é, literalmente, "um fim e uma esperança" (acharit vetiqvah). Deus enxerga o final da história.',
    'Os versículos seguintes completam: "Então me invocareis... buscar-me-eis e me achareis quando me buscardes de todo o vosso coração" (v. 12-13). O plano de Deus não é só um destino; é um encontro. O exílio seria o lugar onde Israel aprenderia a buscá-lo mesmo sem o templo.'],
  ecos: [[24, 29, 7, 'Procurai a paz da cidade'], [45, 8, 28, 'Todas as coisas cooperam para o bem'], [23, 55, 8, 'Os meus pensamentos não são os vossos']],
  pr: 'Pense num lugar da sua vida que parece um exílio. Faça hoje algo para buscar o bem (o shalom) desse lugar, em vez de só esperar sair dele.',
  q: ['Você tem lido as promessas de Deus como atalho ou como companhia para o caminho longo?', 'Como buscar a paz do lugar onde você está agora?'],
  or: 'Senhor, tu conheces os planos que tens para mim, mesmo quando não os entendo. Ensina-me a ser fiel onde estou e a te buscar de todo o coração. Amém.' },

{ r: [4, 6, 24], t: 'A bênção que guarda',
  ctx: 'A bênção sacerdotal (Nm 6:24-26) foi entregue a Arão e seus filhos para abençoar Israel. Em 1979, em Ketef Hinnom, Jerusalém, arqueólogos encontraram dois pequenos rolos de prata, de cerca de 600 a.C., com este texto gravado. É o trecho bíblico mais antigo já encontrado.',
  w: ['יִשְׁמְרֶךָ', 'yishmerekha', '"Te guarde", de shamar: vigiar, proteger, como o pastor guarda o rebanho ou a sentinela vigia a cidade. É o mesmo verbo de Gn 2:15, quando Adão recebe o jardim para cultivar e guardar.'],
  p: ['A bênção tem três linhas que vão crescendo: em hebraico a primeira tem 3 palavras, a segunda 5 e a terceira 7, como uma luz que se abre. O nome do Senhor (YHWH) aparece uma vez em cada linha. Toda bênção vem dele, não do sacerdote.',
    'Todos os verbos estão no singular: "te abençoe", "te guarde". Embora dirigida ao povo inteiro, a bênção fala com cada pessoa como se ela fosse a única. Deus não abençoa uma multidão anônima; abençoa você.',
    'O versículo 27 explica o sentido: "Assim porão o meu nome sobre os filhos de Israel, e eu os abençoarei". Ser abençoado é carregar o nome de Deus, pertencer a ele. E a bênção termina em shalom: a última palavra é paz.'],
  ecos: [[19, 67, 1, 'Faça resplandecer o seu rosto sobre nós'], [19, 121, 7, 'O Senhor te guardará de todo mal'], [47, 13, 14, 'A bênção de Paulo: graça, amor e comunhão']],
  pr: 'Abençoe alguém hoje com estas palavras: em voz alta, numa mensagem ou orando por essa pessoa.',
  q: ['Você recebe a bênção de Deus como algo pessoal, dirigido a você?', 'Quem precisa ouvir uma bênção sua hoje?'],
  or: 'Senhor, abençoa-me e guarda-me. Faze resplandecer o teu rosto sobre mim e dá-me a tua paz. E faze de mim uma bênção para outros. Amém.' },

{ r: [19, 46, 10], t: 'Aquietai-vos',
  ctx: 'O Salmo 46 é dos filhos de Corá, levitas cantores do templo. Pode ter sido inspirado pela libertação de Jerusalém do cerco assírio em 701 a.C. (2Rs 19). Foi o salmo que inspirou Lutero a escrever o hino "Castelo forte é nosso Deus".',
  w: ['הַרְפּוּ', 'harpu', '"Aquietai-vos", de raphah: soltar, afrouxar, deixar as mãos caírem. Está mais para "larguem!" do que para "fiquem quietinhos".'],
  p: ['Esta frase costuma ser lida como convite a um momento calmo de devoção. No salmo, porém, ela vem depois de terremotos, mares em fúria, nações em guerra, e de Deus que "quebra o arco e despedaça a lança" (v. 9). É Deus falando às nações em conflito e ao seu povo aflito: parem, larguem as armas.',
    'Harpu é soltar o que se agarra com força: as armas, o controle, a ansiedade de resolver tudo. "E sabei que eu sou Deus": o conhecimento de Deus vem depois do soltar. Enquanto seguramos tudo com as próprias mãos, não sobra espaço para descobrir quem ele é.',
    'O refrão do salmo (v. 7 e 11) diz: "O Senhor dos Exércitos está conosco; o Deus de Jacó é o nosso refúgio". O Deus dos exércitos é também o Deus de Jacó, aquele que lutou, enganou e fugiu, e mesmo assim foi alcançado pela graça. O refúgio não é só para os fortes.'],
  ecos: [[2, 14, 14, 'O Senhor pelejará por vós'], [23, 30, 15, 'No sossego e na confiança está a vossa força'], [40, 11, 28, 'Vinde a mim e eu vos aliviarei']],
  pr: 'Fique três minutos em silêncio. Abra as mãos sobre os joelhos, como sinal de que solta o que vem tentando controlar.',
  q: ['O que você está segurando com força demais?', 'Como seria "saber que ele é Deus" na sua situação de hoje?'],
  or: 'Senhor, eu solto as minhas armas e o meu controle. Quero saber que tu és Deus. Sê o meu refúgio hoje. Amém.' },

{ r: [20, 9, 10], t: 'Onde começa a sabedoria',
  ctx: 'Provérbios 9 encerra a primeira parte do livro com duas mulheres que convidam para um banquete: a Sabedoria (v. 1-6) e a Insensatez (v. 13-18). As duas chamam "os simples" com quase as mesmas palavras. O versículo 10 fica entre elas, como a chave para escolher.',
  w: ['חָכְמָה', 'chokhmah', 'Sabedoria. Em Êx 31:3-6 a mesma palavra descreve a habilidade dos artesãos que construíram o tabernáculo. Na Bíblia, sabedoria é a arte de viver bem, como um ofício bem feito.'],
  p: ['"O temor do Senhor é o princípio da sabedoria" (techillat chokhmah). Princípio aqui é o ponto de partida, o alicerce, e não uma etapa que se deixa para trás. Assim como não se constrói uma casa sem fundação, não se constrói uma vida sábia sem reverência a Deus.',
    'Temor (yir’ah) não é pavor. É reverência, assombro diante de quem Deus é, que nos leva a levar a sério o que ele diz. Quem teme a Deus não precisa temer mais nada (Sl 112:1, 7). O temor do Senhor coloca todos os outros medos no lugar.',
    'A segunda metade do versículo completa: "e o conhecimento do Santo é entendimento". Em hebraico, "Santo" está no plural (qedoshim), indicando majestade. Sabedoria não é acumular informação; é conhecer alguém, o Santo. Por isso pessoas simples podem ser muito sábias.'],
  ecos: [[18, 28, 28, 'O temor do Senhor é a sabedoria'], [19, 111, 10, 'O princípio da sabedoria'], [59, 3, 17, 'A sabedoria que vem do alto']],
  pr: 'Antes de reagir a algo hoje, pergunte: "O que agradaria a Deus aqui?" Deixe a reverência a ele guiar a resposta.',
  q: ['Qual convite tem soado mais alto na sua vida: o da sabedoria ou o da insensatez?', 'O seu temor de Deus é reverência ou medo de castigo?'],
  or: 'Santo Deus, ensina-me a te temer com reverência e amor. Que a minha sabedoria comece em ti e seja aprendida no dia a dia. Amém.' },

{ r: [21, 3, 1], t: 'Cada coisa no seu tempo',
  ctx: 'Eclesiastes (Qohelet, "aquele que reúne a assembleia") reflete sobre o sentido da vida "debaixo do sol". O livro é honesto sobre a frustração: tudo parece hevel, "vapor, sopro", palavra traduzida como "vaidade". O poema dos tempos (3:1-8) tem catorze pares de opostos.',
  w: ['עֵת', 'et', 'Tempo, ocasião, o momento certo. Diferente de zeman, que é o prazo ou a data marcada, et é a hora propícia para que algo aconteça.'],
  p: ['São catorze pares: nascer e morrer, plantar e arrancar, chorar e rir, calar e falar. Sete é o número da completude, e catorze é o dobro. O poema abraça a vida inteira, inclusive o que dói. Não há pressa nem negação: cada coisa tem a sua hora.',
    'O versículo 11 é a chave: Deus "fez tudo formoso no seu tempo; também pôs a eternidade no coração do homem, sem que este possa descobrir a obra que Deus fez desde o princípio até o fim". Vivemos no tempo, mas temos sede do eterno. Por isso nenhum momento nos satisfaz por completo.',
    'Aceitar os tempos não é fatalismo. É sabedoria para perguntar: que tempo é este? Às vezes lutamos para rir num tempo de chorar, ou insistimos em plantar quando é hora de arrancar. Reconhecer a estação da vida é o primeiro passo para viver bem nela.'],
  ecos: [[19, 31, 15, 'Os meus tempos estão nas tuas mãos'], [48, 6, 9, 'A seu tempo ceifaremos'], [48, 4, 4, 'Na plenitude dos tempos']],
  pr: 'Complete a frase: "Este é um tempo de ______." Depois pergunte a Deus o que é ser fiel nessa estação.',
  q: ['Em que estação da vida você está?', 'Você está lutando contra o tempo presente, desejando outro?'],
  or: 'Senhor da eternidade, os meus tempos estão nas tuas mãos. Dá-me sabedoria para reconhecer a estação e viver nela com fé. Amém.' },

{ r: [35, 2, 4], t: 'O justo viverá pela fidelidade',
  ctx: 'Habacuque profetizou pouco antes da invasão babilônica, por volta de 605 a.C. O livro é um diálogo. O profeta reclama da injustiça (1:2-4); Deus responde que enviará os babilônios (1:5-11); o profeta reclama de novo: como Deus pode usar um povo ainda pior? (1:12-17). Então ele sobe à torre de vigia para esperar a resposta (2:1).',
  w: ['אֱמוּנָתוֹ', 'emunato', '"A sua fé, a sua fidelidade", de emunah, raiz aman: ser firme, confiável. Da mesma raiz vem "amém". Emunah é uma fé que se mantém de pé.'],
  p: ['A resposta de Deus não explica tudo. Ele manda escrever a visão em tábuas, porque ela "se apressa para o fim e não falhará; se tardar, espera-a" (2:3). Então vem o contraste: o soberbo, inchado de si, não é reto; "mas o justo viverá pela sua fé".',
    'Emunah é mais que acreditar em algo; é permanecer firme, ser fiel. O justo não vive de entender os porquês, mas de se manter agarrado a Deus enquanto espera. A fé, aqui, é um modo de viver no intervalo entre a promessa e o cumprimento.',
    'Este versículo atravessa a Bíblia: Paulo o cita em Romanos 1:17 e Gálatas 3:11, e Hebreus em 10:38. Lutero o chamou de porta do paraíso. E o livro termina com um dos atos de fé mais bonitos da Escritura: "ainda que a figueira não floresça... todavia eu me alegrarei no Senhor" (3:17-18).'],
  ecos: [[45, 1, 17, 'O justo viverá da fé'], [58, 10, 38, 'Não somos dos que retrocedem'], [35, 3, 17, 'Ainda que a figueira não floresça']],
  pr: 'Escreva a sua própria versão de Habacuque 3:17-18: "Ainda que ______, todavia eu me alegrarei no Senhor."',
  q: ['Você precisa de explicação para continuar crendo?', 'Qual promessa você está esperando que ainda tarda?'],
  or: 'Senhor, nem sempre entendo os teus caminhos. Dá-me uma fé que permaneça de pé. Ainda que as coisas faltem, quero me alegrar em ti. Amém.' },

{ r: [19, 27, 1], t: 'Luz e salvação',
  ctx: 'Salmo de Davi, provavelmente de um tempo de perseguição. Os versículos 1 a 6 são de confiança; os versículos 7 a 14 são de súplica. O mesmo homem que declara não ter medo pede logo depois: "não me escondas o teu rosto". Fé e luta convivem.',
  w: ['אוֹרִי', 'ori', '"Minha luz." A primeira palavra criadora de Deus foi "haja luz" (Gn 1:3). Chamar Deus de "minha luz" é dizer que ele faz comigo o que fez no começo do mundo: tira da escuridão.'],
  p: ['Luz, salvação e fortaleza (ma’oz, refúgio fortificado): três imagens de proteção. Luz para quem está no escuro e não sabe o caminho; salvação para quem está cercado; fortaleza para quem precisa de abrigo. Deus é tudo isso, e por isso a pergunta: "a quem temerei?"',
    'O centro do salmo é o versículo 4: "Uma coisa pedi ao Senhor, e a buscarei: que eu possa morar na casa do Senhor... para contemplar a formosura do Senhor". Cercado de inimigos, Davi não pede primeiro a vitória; pede a presença. Quem tem uma só prioridade não se divide entre tantos medos.',
    'O salmo termina com um conselho que Davi dá a si mesmo: "Espera no Senhor, anima-te, e ele fortalecerá o teu coração; espera, pois, no Senhor" (v. 14). A palavra "espera" aparece duas vezes. Confiança não é um sentimento instantâneo; é uma decisão repetida.'],
  ecos: [[23, 60, 19, 'O Senhor será a tua luz perpétua'], [43, 8, 12, 'Eu sou a luz do mundo'], [62, 1, 5, 'Deus é luz, e nele não há trevas']],
  pr: 'Qual é a "uma coisa" que você mais deseja de Deus? Escreva e ore por ela hoje.',
  q: ['Que medos têm disputado espaço com a sua confiança?', 'Qual é a "uma coisa" que você busca acima das outras?'],
  or: 'Senhor, tu és a minha luz e a minha salvação; a quem temerei? Que eu busque uma coisa acima de todas: estar contigo. Amém.' },

{ r: [23, 26, 3], t: 'Paz sobre paz',
  ctx: 'Os capítulos 24 a 27 de Isaías são chamados de "Apocalipse de Isaías": visões do juízo sobre a terra e da salvação final. O capítulo 26 é um cântico que seria entoado "naquele dia" em Judá, celebrando uma cidade forte cujos muros são a salvação de Deus (v. 1).',
  w: ['שָׁלוֹם שָׁלוֹם', 'shalom shalom', 'O hebraico repete a palavra para dar intensidade: paz completa, paz sobre paz. A repetição é uma forma hebraica de superlativo.'],
  p: ['"Tu conservarás em perfeita paz aquele cujo propósito é firme." Em hebraico é yetser samukh: a mente, o modo de pensar, "apoiado, sustentado". É uma mente encostada em Deus. A paz não vem de uma mente vazia, mas de uma mente apoiada no lugar certo.',
    '"Porque ele confia em ti" (batuach) usa de novo batach, apoiar-se. O versículo seguinte explica o motivo: "Confiai no Senhor perpetuamente, porque o Senhor Deus é uma rocha eterna" (v. 4). A paz completa pede um apoio que não se mova. Pessoas, planos e saúde mudam; a Rocha não muda.',
    'Repare que Deus é o sujeito: "tu conservarás" (titsor, guardar como uma sentinela). A paz não é algo que produzimos com técnica; é algo que Deus guarda em nós, como se guarda uma cidade. A nossa parte é manter a mente apoiada nele.'],
  ecos: [[50, 4, 7, 'A paz que guarda o coração e a mente'], [43, 14, 27, 'Deixo-vos a paz, a minha paz vos dou'], [19, 4, 8, 'Em paz me deito e logo pego no sono']],
  pr: 'Quando a ansiedade aparecer hoje, repita: "Shalom, shalom: tu és a rocha eterna."',
  q: ['Onde a sua mente tem se apoiado?', 'Que tipo de paz você tem buscado: a que o mundo oferece ou a que Deus guarda?'],
  or: 'Rocha eterna, apoio em ti a minha mente. Guarda-me em paz completa, mesmo quando tudo à minha volta se move. Amém.' },

{ r: [5, 31, 6], t: 'Ele não te deixará',
  ctx: 'Moisés, aos 120 anos, sabe que não entrará na terra (Dt 31:2). Ele se despede de Israel e passa a liderança a Josué. Suas palavras não falam do que ele fará pelo povo, mas do que Deus fará sem ele.',
  w: ['לֹא יַרְפְּךָ', 'lo yarpekha', '"Não te deixará", de raphah: soltar, afrouxar a mão. Deus não afrouxa a mão que segura o seu povo. É o mesmo verbo do "aquietai-vos" do Salmo 46:10.'],
  p: ['Imagine o medo do povo: o líder que os tirou do Egito, que falava com Deus face a face, ia morrer. Moisés responde redirecionando a confiança: "O Senhor teu Deus é quem vai contigo". O apoio do povo não podia ser Moisés; tinha de ser Deus. Todo líder humano um dia vai embora.',
    '"Não te deixará nem te desamparará": são dois verbos, raphah (afrouxar) e azav (abandonar). Deus não vai soltando aos poucos nem abandona de uma vez. É uma promessa contra dois medos: o de ir sendo esquecido devagar e o de ser largado de repente.',
    'A promessa é tão importante que é repetida a Josué (Dt 31:8; Js 1:5), a Salomão (1Cr 28:20) e citada em Hebreus 13:5 para cristãos ansiosos com dinheiro: "contentai-vos com o que tendes, porque ele disse: de maneira alguma te deixarei".'],
  ecos: [[6, 1, 5, 'Como fui com Moisés, assim serei contigo'], [58, 13, 5, 'Nunca te deixarei, jamais te abandonarei'], [40, 28, 20, 'Estou convosco todos os dias']],
  pr: 'Pense numa pessoa ou segurança que você tem medo de perder. Entregue-a a Deus em oração e declare que ele não te soltará.',
  q: ['Em quem ou em que a sua segurança está apoiada, além de Deus?', 'Qual medo é maior em você: ser esquecido aos poucos ou abandonado de uma vez?'],
  or: 'Senhor, pessoas e seguranças passam, mas tu não me soltas. Obrigado por ires adiante de mim. Amém.' },

{ r: [19, 34, 8], t: 'Provai e vede',
  ctx: 'O título liga o salmo ao episódio em que Davi fingiu loucura diante de um rei filisteu para escapar (1Sm 21:10-15; no título o rei é chamado Abimeleque). Davi estava fugindo, humilhado, sem nada. Desse momento nasce um salmo de louvor, que também é um acróstico.',
  w: ['טַעֲמוּ', 'ta’amu', '"Provai", de ta’am: provar com a boca, saborear. O substantivo ta’am também significa "juízo, discernimento", e é a palavra usada em 1Sm 21:13 quando Davi "mudou o seu juízo" para parecer louco.'],
  p: ['Há aqui um jogo de palavras bonito. Davi mudou o seu ta’am, fingiu perder o juízo, para escapar com vida. Agora ele convida: "provai (ta’amu) e vede que o Senhor é bom". Quando perdeu tudo, até a dignidade, descobriu o sabor da bondade de Deus.',
    '"Provai e vede": a ordem é curiosa. Primeiro provar, depois ver. Normalmente queremos ver para depois experimentar. Com Deus, a compreensão vem da experiência. Ninguém conhece um sabor por descrição; é preciso comer.',
    'O versículo 18 completa: "Perto está o Senhor dos que têm o coração quebrantado". O salmo nasceu de um homem quebrado. A bondade de Deus tem mais sabor justamente quando estamos com fome.'],
  ecos: [[60, 2, 3, 'Se é que já provastes que o Senhor é bom'], [19, 63, 5, 'A minha alma se farta como de banha'], [43, 6, 35, 'Eu sou o pão da vida']],
  pr: 'Dê hoje um passo concreto de confiança em algo que você vem adiando por falta de certeza. Prove a fidelidade de Deus na prática.',
  q: ['Você tem esperado ver antes de provar?', 'Em que momento difícil você provou a bondade de Deus?'],
  or: 'Senhor, quero provar e ver a tua bondade. Mesmo quando estou quebrado, sei que estás perto. Amém.' },

{ r: [19, 37, 4], t: 'Deleita-te no Senhor',
  ctx: 'Salmo de Davi já idoso (v. 25: "fui moço e agora sou velho"). É um acróstico de sabedoria sobre um problema antigo: por que os maus prosperam? A resposta repetida é "não te indignes" (v. 1, 7 e 8).',
  w: ['הִתְעַנַּג', 'hit’anag', '"Deleita-te", de anag: ser delicado, ter prazer, deliciar-se. Em Isaías 58:14 e 66:11 descreve a alegria de quem se farta num banquete.'],
  p: ['O versículo é muitas vezes lido como fórmula: deleite-se em Deus e ele lhe dará o que você quiser. Mas quando Deus se torna o nosso deleite, os nossos desejos mudam. Ele dá "os desejos do coração" no sentido mais profundo: forma em nós desejos que ele tem prazer em realizar.',
    'O salmo sobe como uma escada de quatro verbos: "confia" (v. 3), "deleita-te" (v. 4), "entrega" (v. 5) e "descansa" (v. 7). Confiar, ter prazer em Deus, entregar o caminho, descansar. A inveja e a irritação com o sucesso dos outros perdem força quando o deleite está em Deus.',
    '"Entrega o teu caminho" usa gol, "rola", a imagem de rolar uma pedra pesada para outro carregar. Os desejos não deixam de importar; deixam de nos dominar.'],
  ecos: [[19, 16, 11, 'Na tua presença há plenitude de alegria'], [40, 6, 33, 'Buscai primeiro o Reino de Deus'], [50, 4, 4, 'Alegrai-vos sempre no Senhor']],
  pr: 'Faça hoje uma pausa para algo que te leve a se alegrar em Deus: um salmo, uma música, uma caminhada olhando a criação.',
  q: ['Deus é o seu deleite ou o caminho para chegar a outros deleites?', 'Que desejos você precisa entregar para que sejam transformados?'],
  or: 'Senhor, quero me deleitar em ti, e não só nos teus presentes. Molda os meus desejos até que sejam os teus. Amém.' },

{ r: [20, 16, 3], t: 'Rolar o peso sobre Deus',
  ctx: 'Provérbios 16 começa com uma série de ditos sobre os planos humanos e a soberania de Deus: "o homem faz planos, mas a resposta vem do Senhor" (v. 1); "o coração do homem traça o seu caminho, mas o Senhor dirige os seus passos" (v. 9).',
  w: ['גֹּל', 'gol', '"Rola", de galal. As traduções "confia" ou "entrega" suavizam a imagem: rolar uma pedra pesada para outro carregar. Da mesma raiz vem Gilgal, o lugar onde Deus "removeu" (literalmente "rolou") a vergonha do Egito (Js 5:9).'],
  p: ['"Rola as tuas obras para o Senhor, e os teus planos serão firmados." Rolar é o gesto de quem reconhece que o peso é grande demais. Não é largar o trabalho, mas tirar das costas o peso do resultado.',
    'Planejar não é condenado. Provérbios elogia quem planeja com diligência (21:5). O que muda é onde os planos se apoiam. "Firmados" (yikonu) é o verbo de algo bem fundado, estável. Planos entregues a Deus ganham fundação.',
    'O versículo 4 avança: "O Senhor fez tudo para um propósito". Nada do que entregamos a Deus se perde. Mesmo quando os planos mudam (v. 9), é ele quem dirige os passos.'],
  ecos: [[19, 37, 5, 'Entrega o teu caminho ao Senhor'], [19, 55, 22, 'Lança o teu fardo sobre o Senhor'], [60, 5, 7, 'Lançai sobre ele toda a vossa ansiedade']],
  pr: 'Liste os seus três principais compromissos de hoje e, um por um, "role-os" para Deus em oração antes de começar.',
  q: ['Você carrega o peso de resultados que só Deus pode garantir?', 'Em que os seus planos estão apoiados?'],
  or: 'Senhor, rolo para ti o meu trabalho e os meus planos. Firma o que for teu e muda o que não for. Amém.' },

{ r: [18, 19, 25], t: 'Meu Redentor vive',
  ctx: 'Jó perdeu os bens, os filhos e a saúde. Os amigos insistem que ele deve ter pecado. No capítulo 19 ele está no fundo do poço: os parentes o abandonaram, a esposa estranha o seu hálito, ele é só pele e osso (v. 13-20). Ele deseja que as suas palavras fossem gravadas na rocha com ferro e chumbo (v. 23-24). E então faz esta declaração.',
  w: ['גֹּאֲלִי', 'go’ali', '"Meu redentor", de go’el: o parente próximo que tinha o dever de resgatar o familiar. Ele recomprava a terra vendida, libertava da escravidão, defendia o sangue derramado e garantia a descendência (Lv 25:25; Rt 3:9).'],
  p: ['O go’el era o parente que entrava em cena quando alguém já não podia se defender. Jó, abandonado por todos os parentes humanos, afirma que tem um parente que não o abandonará: o próprio Deus. Quando todos os laços se rompem, ainda existe um Redentor.',
    '"E por fim se levantará sobre a terra": acharon, "o último". Os amigos falaram, Jó falou, mas a última palavra será de Deus. Em meio a uma dor sem explicação, Jó não tem respostas, mas tem uma certeza: a história não termina na sua miséria.',
    '"Depois de consumida esta minha pele, ainda em minha carne verei a Deus" (v. 26). O hebraico deste trecho é difícil e há debate sobre o sentido exato, mas Jó claramente espera ver Deus com os próprios olhos (v. 27), e acrescenta: "o meu coração desfalece dentro de mim", de saudade.'],
  ecos: [[8, 4, 14, 'Bendito o Senhor, que não te deixou sem redentor'], [23, 54, 5, 'O Santo de Israel é o teu Redentor'], [46, 15, 20, 'Cristo ressuscitou, primícias dos que dormem']],
  pr: 'Pense em alguém que está sofrendo sem explicação. Ore por essa pessoa e, se puder, faça-lhe companhia sem tentar dar respostas.',
  q: ['Você precisa de respostas para crer, ou de presença?', 'Em quem você tem buscado uma redenção que só Deus pode dar?'],
  or: 'Meu Redentor, tu vives. Quando não entendo o que acontece, quero me agarrar à certeza de que a última palavra é tua. Amém.' },

{ r: [19, 1, 2], t: 'Meditar de dia e de noite',
  ctx: 'O Salmo 1 é a porta de entrada do Saltério e apresenta dois caminhos: o do justo e o do ímpio. Ele começa com a palavra ashrei, "feliz", e o Salmo 2 termina com ela. Os dois juntos formam uma moldura de felicidade para o livro inteiro.',
  w: ['יֶהְגֶּה', 'yehgeh', '"Medita", de hagah: murmurar, falar baixinho. Em Isaías 31:4 descreve o rosnado baixo do leão sobre a presa. Meditar é ruminar em voz baixa, repetindo.'],
  p: ['O versículo 1 descreve uma queda em três degraus: andar no conselho dos ímpios, deter-se no caminho dos pecadores, assentar-se na roda dos escarnecedores. Andar, parar, sentar. A má influência vai nos acomodando aos poucos.',
    'O contraste não é só evitar o mal, mas ter prazer (chefets) na Torá. Torah significa "instrução, ensino", como o de um pai para o filho. Quem tem prazer na instrução de Deus não precisa ser forçado a lê-la.',
    'O versículo 3 mostra o resultado: uma "árvore plantada junto a correntes de águas". O verbo shatul indica uma muda plantada ali de propósito: a árvore não nasceu ali, foi colocada perto da água. Ninguém nasce firme; somos levados para perto da água pela meditação constante.'],
  ecos: [[6, 1, 8, 'Medita nele de dia e de noite'], [24, 17, 8, 'Como a árvore plantada junto às águas'], [51, 3, 16, 'A palavra de Cristo habite em vós ricamente']],
  pr: 'Escolha um versículo curto e repita-o em voz baixa várias vezes ao longo do dia, como quem rumina.',
  q: ['Em qual degrau (andar, parar, sentar) você percebe más influências se acomodando?', 'A sua leitura da Palavra é obrigação ou prazer?'],
  or: 'Senhor, planta-me perto das tuas águas. Que a tua instrução seja o meu prazer e o meu murmúrio de dia e de noite. Amém.' },

{ r: [23, 55, 9], t: 'Caminhos mais altos',
  ctx: 'Isaías 55 é um convite ao banquete gratuito de Deus: "Ó vós, todos os que tendes sede, vinde às águas... comprai sem dinheiro" (v. 1). Dirigido a exilados que achavam que Deus os tinha abandonado, o capítulo chama ao arrependimento e promete perdão abundante (v. 7).',
  w: ['גָבְהוּ', 'gavehu', '"São mais altos", de gavah: ser alto, elevado. Dito de uma pessoa, pode ter sentido negativo (orgulho, altivez); dito de Deus, expressa a sua grandeza.'],
  p: ['Este versículo costuma ser usado para dizer "não entendemos Deus". O contexto é mais específico. O versículo 7 fala do perdão: "volte-se para o Senhor, que se compadecerá dele... porque é rico em perdoar". O que está tão acima dos nossos pensamentos é, antes de tudo, a medida do perdão de Deus.',
    'Nós perdoamos com limites, contamos as vezes, guardamos lembranças. Os caminhos de Deus são mais altos: ele perdoa em abundância (yarbeh lisloach). A distância entre o céu e a terra mede a diferença entre a nossa graça e a dele.',
    'Os versículos 10 e 11 completam: assim como a chuva desce e não volta sem regar a terra, a palavra de Deus não volta vazia. Os pensamentos de Deus não ficam presos lá no alto; descem como chuva e fazem a vida brotar.'],
  ecos: [[19, 103, 12, 'Quanto dista o oriente do ocidente'], [45, 11, 33, 'Ó profundidade da riqueza'], [40, 18, 22, 'Setenta vezes sete']],
  pr: 'Pense em alguém que você tem dificuldade de perdoar. Peça a Deus que te ensine a perdoar pelos caminhos mais altos dele.',
  q: ['Você tem medido o perdão de Deus pelo seu próprio?', 'Que área da sua vida precisa da chuva da Palavra?'],
  or: 'Senhor, o teu perdão é mais alto que os céus. Obrigado. Ensina-me a perdoar como tu me perdoas. Amém.' },

{ r: [29, 2, 13], t: 'Rasgai o coração',
  ctx: 'Joel fala depois de uma praga de gafanhotos que devastou Judá (cap. 1), vista como sinal do "Dia do Senhor". No antigo Israel, rasgar as roupas era o sinal público de luto ou de arrependimento (Gn 37:34; 2Rs 19:1).',
  w: ['שׁוּבוּ', 'shuvu', '"Voltai", de shuv: dar meia-volta, retornar. É a principal palavra para arrependimento no Tanakh: mudar de direção, e não só de sentimento.'],
  p: ['"Rasgai o vosso coração, e não as vossas vestes." Joel não proíbe o gesto externo; ele aponta para o que precisa acontecer por dentro. É possível rasgar a roupa sem que nada mude no coração. Deus quer o arrependimento que transforma.',
    'O motivo para voltar não é o medo, mas o caráter de Deus: "porque ele é misericordioso, compassivo, tardio em irar-se e grande em benignidade". Joel cita Êxodo 34:6, quando Deus revelou o seu nome a Moisés. Voltamos porque sabemos quem nos espera.',
    'O versículo 14 tem uma humildade bonita: "Quem sabe se não se voltará e se arrependerá?" O profeta não manipula Deus nem garante resultado. Convida a voltar e deixa a resposta com Deus. Mais adiante, Joel promete o derramamento do Espírito (2:28), que Pedro cita no Pentecostes (At 2:17).'],
  ecos: [[2, 34, 6, 'Misericordioso e piedoso, tardio em irar-se'], [19, 51, 17, 'Um coração quebrantado e contrito'], [42, 15, 20, 'O pai correu ao encontro do filho']],
  pr: 'Identifique um hábito ou atitude que precisa de meia-volta. Dê hoje um passo concreto na direção contrária.',
  q: ['O seu arrependimento tem sido de roupas ou de coração?', 'O que te faz voltar para Deus: medo ou o conhecimento de quem ele é?'],
  or: 'Senhor misericordioso, rasga o meu coração, e não apenas as minhas aparências. Eu volto para ti, sabendo que és grande em bondade. Amém.' },

{ r: [19, 90, 12], t: 'Contar os dias',
  ctx: 'É o único salmo atribuído a Moisés, "homem de Deus", e abre o Livro IV dos Salmos. Ele contrasta a eternidade de Deus ("de eternidade a eternidade, tu és Deus", v. 2) com a brevidade humana: "setenta anos, ou, havendo vigor, oitenta" (v. 10).',
  w: ['לִמְנוֹת', 'limnot', '"Contar", de manah: contar, numerar, avaliar. Da mesma raiz vem maneh, uma medida de peso. Contar é pesar o valor de algo.'],
  p: ['"Ensina-nos a contar os nossos dias" não é um pedido de matemática; Moisés sabe a idade que tem. É um pedido de sabedoria: viver sabendo que os dias são poucos e pesá-los com cuidado. Quem esquece que a vida é breve a desperdiça; quem se lembra, a valoriza.',
    '"Para que alcancemos coração sábio": o resultado de contar os dias é um coração que escolhe bem. A brevidade não é motivo de desespero, mas de foco. Ela separa o essencial do supérfluo.',
    'O salmo termina pedindo: "Sacia-nos de manhã com a tua benignidade" (v. 14) e "confirma a obra das nossas mãos" (v. 17). Diante da brevidade, Moisés não pede mais anos; pede anos cheios da bondade de Deus e um trabalho que permaneça.'],
  ecos: [[19, 39, 4, 'Dá-me a conhecer o meu fim'], [59, 4, 14, 'A vida é um vapor'], [49, 5, 16, 'Remindo o tempo']],
  pr: 'Antes de dormir, pergunte: "Se este dia fosse pesado, o que teria valor?" Escolha uma coisa para fazer amanhã com mais intenção.',
  q: ['Você tem vivido como se o tempo fosse infinito?', 'Que "obra das suas mãos" você gostaria que permanecesse?'],
  or: 'Deus eterno, ensina-me a contar os meus dias. Sacia-me com a tua bondade e confirma a obra das minhas mãos. Amém.' },

{ r: [2, 14, 14], t: 'O Senhor pelejará por vós',
  ctx: 'Israel acabara de sair do Egito. Encurralado entre o mar e o exército do faraó, o povo entra em pânico e acusa Moisés: "Não havia sepulturas no Egito?" (v. 11). A resposta de Moisés é este versículo.',
  w: ['תַּחֲרִשׁוּן', 'tacharishun', '"Vos calareis", de charash: ficar em silêncio, emudecer. É o silêncio de quem para de reclamar e espera Deus agir.'],
  p: ['"O Senhor pelejará por vós, e vós vos calareis." O povo queria fazer barulho: reclamar, culpar Moisés, voltar atrás. A ordem vai contra a intuição: a vitória não viria da agitação. Há batalhas em que a nossa parte é ficar quietos e ver Deus agir.',
    'Curiosamente, no versículo seguinte Deus diz a Moisés: "Por que clamas a mim? Dize aos filhos de Israel que marchem" (v. 15). Calar não é ficar parado. O povo devia parar de reclamar e começar a andar, em direção ao mar. A fé caminha mesmo antes de o caminho se abrir.',
    'O mar se abre durante a noite com um vento oriental (v. 21). Israel atravessa a seco e, do outro lado, canta um dos cânticos mais antigos da Bíblia (Êx 15). O silêncio de hoje pode se tornar o cântico de amanhã.'],
  ecos: [[14, 20, 15, 'A peleja não é vossa, mas de Deus'], [19, 46, 10, 'Aquietai-vos e sabei'], [45, 8, 31, 'Se Deus é por nós']],
  pr: 'Hoje, quando sentir vontade de reclamar de algo que você não controla, troque a reclamação por um passo de obediência.',
  q: ['Que batalha você tem tentado vencer pelo barulho?', 'Qual é o passo à frente que Deus te pede, mesmo antes de o mar se abrir?'],
  or: 'Senhor, tu pelejas por mim. Silencia a minha reclamação e dá-me coragem para marchar enquanto abres o caminho. Amém.' },

{ r: [5, 6, 4], t: 'Shemá, Israel',
  ctx: 'O Shemá é a confissão central de Israel. Foi dito a um povo que ia entrar numa terra de muitos deuses: Baal da chuva e da tempestade, Aserá da fertilidade, entre outros. Até hoje é recitado pelos judeus duas vezes ao dia, e foi a última palavra de muitos mártires.',
  w: ['שְׁמַע', 'shema', '"Ouve", de shama. Em hebraico, ouvir inclui obedecer; não existe outra palavra comum para "obedecer". Ouvir de verdade é fazer.'],
  p: ['"Ouve, Israel: o Senhor nosso Deus é o único Senhor" (ou "o Senhor é o nosso Deus, o Senhor é um"). Nos rolos da Torá, duas letras deste versículo são escritas maiores: o ayin de shema e o dalet de echad. Juntas formam ed, "testemunha". Quem recita o Shemá se torna testemunha.',
    'Echad, "um", não fala só de quantidade. Fala de exclusividade e de inteireza: Deus não divide o seu lugar. Num mundo de muitos deuses, cada um responsável por uma área da vida, o Shemá afirma que um só Deus reina sobre a chuva, a colheita, a família e a guerra. Nenhuma área pertence a outro senhor.',
    'Jesus citou o Shemá quando lhe perguntaram qual era o maior mandamento (Mc 12:29). Para ele, a fé começa com ouvir. Antes de falar com Deus, ouvimos o que ele diz de si mesmo.'],
  ecos: [[41, 12, 29, 'Jesus cita o Shemá'], [23, 45, 5, 'Eu sou o Senhor, e não há outro'], [46, 8, 6, 'Para nós há um só Deus']],
  pr: 'Separe alguns minutos de silêncio para ouvir: leia um trecho bíblico devagar, sem pressa de terminar.',
  q: ['Que "outros deuses" disputam áreas da sua vida?', 'Você tem ouvido para obedecer ou só para saber?'],
  or: 'Ouve, minha alma: o Senhor é o meu Deus, o único. Reina em todas as áreas da minha vida. Que eu ouça e obedeça. Amém.' },

{ r: [1, 28, 15], t: 'Contigo estou',
  ctx: 'Jacó foge de casa depois de enganar o irmão Esaú e o pai, Isaque. Sozinho, à noite, dorme ao relento com uma pedra por travesseiro. Sonha com uma escada entre o céu e a terra e ouve Deus repetir para ele a promessa feita a Abraão.',
  w: ['עִמָּךְ', 'immakh', '"Contigo", de im, "com". A presença de Deus é o centro da promessa: antes de "eu te darei", vem "eu estou contigo".'],
  p: ['Jacó não merecia esta visita. Acabara de mentir e de tomar a bênção do irmão. Não estava orando nem buscando Deus; estava fugindo. Mesmo assim Deus aparece e promete: "eis que eu estou contigo". A graça encontra Jacó no pior momento, antes de ele mudar.',
    'A promessa tem quatro partes: estou contigo, te guardarei por onde quer que fores, te farei voltar a esta terra, não te deixarei até cumprir o que te disse. Deus se compromete com o caminho inteiro, incluindo os vinte anos difíceis que Jacó passaria com Labão (Gn 31:41).',
    'Jacó acorda e diz: "Na verdade o Senhor está neste lugar, e eu não o sabia" (v. 16). Ele chama o lugar de Betel, "casa de Deus". Lugares comuns, um descampado e uma pedra, podem ser casa de Deus. Muitas vezes Deus já está onde estamos; nós é que não sabíamos.'],
  ecos: [[43, 1, 51, 'Jesus, a escada entre o céu e a terra'], [50, 1, 6, 'Aquele que começou a boa obra a completará'], [40, 28, 20, 'Estou convosco todos os dias']],
  pr: 'Em algum momento de hoje, pare onde estiver e diga: "O Senhor está neste lugar."',
  q: ['Você acha que precisa merecer a presença de Deus?', 'Que lugar comum da sua vida pode se tornar um Betel?'],
  or: 'Deus de Jacó, obrigado por me encontrar até quando fujo. Abre os meus olhos para perceber que estás neste lugar. Amém.' },
];

// Índice do dia (muda à meia-noite no horário do aparelho).
function dayIndex(date = new Date()) {
  const d = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
  return Math.floor(d / 86400000) % DAILY.length;
}
